mapper.select:
select goods.id as goodsId, goods.name as goodsName, goods.introduce, goods.images, goods.price, goods.stock, goods.sort_introduce, goods.class_id as classId, class.name as className, goods.status from goods as goods inner join class as class on class.id = goods.class_id where 1=1
and class.parent_id=#{listVto.classId}
and goods.name like CONCAT('%',#{listVto.likeName},'%')
